import React, { useState } from 'react';

const Header = () => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navLinks = [
    { label: 'Home', href: '/' },
    { label: 'About', href: '/about' },
    { label: 'Solutions', href: '/solutions' },
    { label: 'Expertise', href: '/expertise' },
    { label: 'Insights', href: '/insights' },
    { label: 'Contact', href: '/contact' },
  ];

  const headerStyle = {
    position: 'sticky',
    top: 0,
    zIndex: 1000,
    backdrop: 'blur(12px)',
  };

  const containerStyle = {
    background: 'rgba(10, 17, 40, 0.7)',
    backdropFilter: 'blur(12px)',
    WebkitBackdropFilter: 'blur(12px)',
    border: '1px solid rgba(255, 255, 255, 0.1)',
    padding: '16px 40px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    maxWidth: '100%',
    margin: '0 auto',
  };

  const logoStyle = {
    color: 'var(--accent-gold)',
    fontSize: '26px',
    fontWeight: '800',
    margin: 0,
    letterSpacing: '-0.5px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
  };

  const logoIconStyle = {
    width: '32px',
    height: '32px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const navContainerStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '40px',
  };

  const navStyle = {
    display: 'flex',
    gap: '32px',
    listStyle: 'none',
    margin: 0,
    padding: 0,
  };

  const navLinkStyle = {
    color: 'rgba(255, 255, 255, 0.8)',
    textDecoration: 'none',
    fontSize: '14px',
    fontWeight: '500',
    letterSpacing: '0.3px',
    position: 'relative',
    transition: 'all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)',
    textTransform: 'capitalize',
  };

  const navLinkHoverStyle = {
    color: 'var(--accent-gold)',
  };

  const ctaButtonStyle = {
    background: 'linear-gradient(135deg, var(--accent-gold), #c4a555)',
    color: 'var(--primary-maroon-dark)',
    padding: '12px 32px',
    border: 'none',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    letterSpacing: '0.3px',
    transition: 'all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)',
    boxShadow: '0 8px 24px rgba(212, 175, 55, 0.2)',
    textDecoration: 'none',
    display: 'inline-flex',
    alignItems: 'center',
    gap: '8px',
    whiteSpace: 'nowrap',
  };

  const ctaButtonHoverStyle = {
    transform: 'translateY(-2px)',
    boxShadow: '0 12px 32px rgba(212, 175, 55, 0.3)',
  };

  const hamburgerStyle = {
    display: 'none',
    flexDirection: 'column',
    gap: '6px',
    cursor: 'pointer',
    background: 'none',
    border: 'none',
    padding: '8px',
  };

  const hamburgerLineStyle = {
    width: '24px',
    height: '2px',
    background: 'var(--accent-gold)',
    borderRadius: '2px',
    transition: 'all 0.3s ease',
  };

  const mobileMenuStyle = {
    display: mobileMenuOpen ? 'flex' : 'none',
    position: 'absolute',
    top: '100%',
    left: 0,
    right: 0,
    flexDirection: 'column',
    background: 'rgba(10, 17, 40, 0.95)',
    backdropFilter: 'blur(12px)',
    WebkitBackdropFilter: 'blur(12px)',
    border: '1px solid rgba(255, 255, 255, 0.1)',
    borderTop: 'none',
    padding: '20px 40px',
    gap: '16px',
    zIndex: 999,
  };

  const mobileNavLinkStyle = {
    color: 'rgba(255, 255, 255, 0.8)',
    textDecoration: 'none',
    fontSize: '15px',
    fontWeight: '500',
    padding: '12px 0',
    borderBottom: '1px solid rgba(255, 255, 255, 0.08)',
    transition: 'color 0.3s ease',
  };

  const mobileCTAStyle = {
    ...ctaButtonStyle,
    width: '100%',
    justifyContent: 'center',
    marginTop: '8px',
  };

  return (
    <header style={headerStyle}>
      <div style={containerStyle}>
        {/* Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer' }}>
          <div style={logoIconStyle}>
            <svg width="32" height="32" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
              <circle cx="24" cy="24" r="22" stroke="currentColor" strokeWidth="1.5" opacity="0.6" />
              <path d="M24 10L35 18V30C35 36 24 42 24 42S13 36 13 30V18L24 10Z" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round" />
              <line x1="18" y1="30" x2="24" y2="36" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
              <line x1="30" y1="30" x2="24" y2="36" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </div>
          <h1 style={logoStyle}>Artemis</h1>
        </div>

        {/* Desktop Navigation */}
        <nav style={{ ...navContainerStyle, '@media (maxWidth: 768px)': { display: 'none' } }}>
          <ul style={navStyle}>
            {navLinks.map((link) => (
              <li key={link.href}>
                <a
                  href={link.href}
                  style={navLinkStyle}
                  onMouseEnter={(e) => {
                    e.target.style.color = 'var(--accent-gold)';
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.color = 'rgba(255, 255, 255, 0.8)';
                  }}
                >
                  {link.label}
                </a>
              </li>
            ))}
          </ul>

          {/* Desktop CTA Button */}
          <a
            href="/contact"
            style={ctaButtonStyle}
            onMouseEnter={(e) => {
              Object.assign(e.currentTarget.style, ctaButtonHoverStyle);
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = '0 8px 24px rgba(212, 175, 55, 0.2)';
            }}
          >
            Request Consultation
            <span style={{ fontSize: '16px' }}>→</span>
          </a>
        </nav>

        {/* Mobile Hamburger Menu */}
        <button
          style={{
            ...hamburgerStyle,
            '@media (minWidth: 769px)': { display: 'none' },
            display: window.innerWidth <= 768 ? 'flex' : 'none',
          }}
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle menu"
        >
          <div style={{
            ...hamburgerLineStyle,
            transform: mobileMenuOpen ? 'rotate(45deg) translateY(10px)' : 'rotate(0)',
          }} />
          <div style={{
            ...hamburgerLineStyle,
            opacity: mobileMenuOpen ? 0 : 1,
            transition: 'opacity 0.3s ease',
          }} />
          <div style={{
            ...hamburgerLineStyle,
            transform: mobileMenuOpen ? 'rotate(-45deg) translateY(-10px)' : 'rotate(0)',
          }} />
        </button>
      </div>

      {/* Mobile Navigation Menu */}
      <div style={mobileMenuStyle}>
        {navLinks.map((link) => (
          <a
            key={link.href}
            href={link.href}
            style={mobileNavLinkStyle}
            onMouseEnter={(e) => {
              e.target.style.color = 'var(--accent-gold)';
            }}
            onMouseLeave={(e) => {
              e.target.style.color = 'rgba(255, 255, 255, 0.8)';
            }}
          >
            {link.label}
          </a>
        ))}
        <a
          href="/contact"
          style={mobileCTAStyle}
          onMouseEnter={(e) => {
            Object.assign(e.currentTarget.style, ctaButtonHoverStyle);
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = 'translateY(0)';
            e.currentTarget.style.boxShadow = '0 8px 24px rgba(212, 175, 55, 0.2)';
          }}
        >
          Request Consultation
          <span style={{ fontSize: '16px' }}>→</span>
        </a>
      </div>
    </header>
  );
};

export default Header;
